// Construct a fuzz-backed in-memory IO and initialize a nestegg context
// We implement a minimal read/seek/tell over a heap-allocated userdata so it
// remains valid for the lifetime of the context. We store the userdata pointer
// on the context via attributes so destroy can free it later.

// Backing buffer for our IO provider (1..4096 bytes, provided by fuzzer)
std::string backing = FUZZ_PARAM_STR();
// Define the userdata layout the callbacks will use
struct FuzzIOState { const unsigned char *data; size_t size; size_t pos; };
// Allocate userdata on heap to survive beyond this stub invocation
FuzzIOState *st = (FuzzIOState *) malloc(sizeof(FuzzIOState));
if (!st) { FUZZ_BAIL(); }
st->data = reinterpret_cast<const unsigned char *>(backing.data());
st->size = backing.size();
st->pos = 0;

// Non-capturing lambdas convert to C function pointers; they have static lifetime
auto read_cb = +[](void *buffer, size_t length, void *userdata) -> int {
  FuzzIOState *s = (FuzzIOState *) userdata;
  if (!s || !buffer) return -1;
  if (s->pos > s->size) return -1;
  size_t remain = s->size - s->pos;
  size_t n = length < remain ? length : remain;
  if (n) { memcpy(buffer, s->data + s->pos, n); s->pos += n; }
  return (int) n; // return bytes read, may be 0 at EOF
};
auto seek_cb = +[](int64_t offset, int whence, void *userdata) -> int {
  FuzzIOState *s = (FuzzIOState *) userdata;
  if (!s) return -1;
  int64_t base = 0;
  if (whence == 0 /*SEEK_SET*/) base = 0;
  else if (whence == 1 /*SEEK_CUR*/) base = (int64_t) s->pos;
  else if (whence == 2 /*SEEK_END*/) base = (int64_t) s->size;
  else return -1;
  int64_t np = base + offset;
  if (np < 0 || (uint64_t) np > s->size) return -1;
  s->pos = (size_t) np;
  return 0;
};
auto tell_cb = +[](void *userdata) -> int64_t {
  FuzzIOState *s = (FuzzIOState *) userdata;
  if (!s) return -1;
  return (int64_t) s->pos;
};

nestegg_io io;
io.read = read_cb;
io.seek = seek_cb;
io.tell = tell_cb;
io.userdata = (void *) st;

// Optionally bound max_offset to either -1 or within our buffer size
uint64_t sz = (uint64_t) backing.size();
int use_bound = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int64_t max_offset = use_bound ? (int64_t) (sz ? (sz - 1) : 0) : (int64_t) -1;

// We pass no logging callback for simplicity and speed
nestegg *context_local = nullptr;
int rc = nestegg_init(&context_local, io, (nestegg_log) nullptr, max_offset);
if (rc != 0 || !context_local) { free(st); FUZZ_BAIL(); }
FUZZ_ASSERT(context_local != nullptr, "nestegg_init must return non-null on success");

// Track IO userdata on the context for lifetime management and for later seeks
FUZZ_SET_ATTR_PTR(context_local, "io_userdata", (void *) st);
FUZZ_SET_ATTR_INT(context_local, "buf_size", (int) (sz > (uint64_t) INT32_MAX ? INT32_MAX : (int32_t) sz));
FUZZ_SET_ATTR_INT(context_local, "read_started", 0);

// Output the live context object
nestegg *context = context_local;

// Destroy a previously initialized context. We also free the heap-allocated
// IO userdata created by our init stub.
void *st = FUZZ_GET_ATTR_PTR(context, "io_userdata");
if (st) { free(st); }
// After calling destroy the context must not be used again
nestegg_destroy(context);
// No outputs returned; the fuzzer runtime will drop this object from the pool.

// Query the stream duration (ns)
uint64_t dur = 0;
int rc = nestegg_duration(context, &dur);
if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive for further calls

// Query timestamp scale (ns)
uint64_t scale = 0;
int rc = nestegg_tstamp_scale(context, &scale);
if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive

// Query number of tracks
unsigned int tracks = 0;
int rc = nestegg_track_count(context, &tracks);
if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive

// Query cue point info for a cluster index. We bound cluster_num to a small range
// and choose max_offset either -1 or within our IO buffer size.
unsigned int cluster_num = (unsigned int) (*FUZZ_PARAM(unsigned int) % 8u);
int have_size = FUZZ_GET_ATTR_INT(context, "buf_size");
int use_bound = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int64_t max_offset = use_bound ? (int64_t) (have_size > 0 ? (have_size - 1) : 0) : (int64_t) -1;
int64_t start_pos = -1, end_pos = -1;
uint64_t tstamp = 0;
int rc = nestegg_get_cue_point(context, cluster_num, max_offset, &start_pos, &end_pos, &tstamp);
if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive

// Seek to an absolute byte offset. We constrain offset to our buffer size.
