uint64_t offset = buf_size > 0 ? ((uint64_t) (*FUZZ_PARAM(unsigned int)) % (uint64_t) buf_size) : 0u;
int rc = nestegg_offset_seek(context, offset);
if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive

// Seek a specific track to a timestamp. We first resolve a valid track index.
