if (nestegg_track_count(context, &tracks) != 0) { FUZZ_BAIL(); }
if (tracks == 0) { FUZZ_BAIL(); }
unsigned int track = (unsigned int) (*FUZZ_PARAM(unsigned int) % tracks);
int cid = nestegg_track_codec_id(context, track);
if (cid < 0) { FUZZ_BAIL(); }
// Keep context alive

// Query the number of codec data chunks for a track
unsigned int tracks = 0;
if (nestegg_track_count(context, &tracks) != 0) { FUZZ_BAIL(); }
if (tracks == 0) { FUZZ_BAIL(); }
unsigned int track = (unsigned int) (*FUZZ_PARAM(unsigned int) % tracks);
unsigned int count = 0;
int rc = nestegg_track_codec_data_count(context, track, &count);
if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive

// Retrieve a specific codec data chunk pointer/length for a track
