if (nestegg_track_count(context, &tracks) != 0) { FUZZ_BAIL(); }
if (tracks == 0) { FUZZ_BAIL(); }
unsigned int track = (unsigned int) (*FUZZ_PARAM(unsigned int) % tracks);
unsigned int count = 0;
if (nestegg_track_codec_data_count(context, track, &count) != 0) { FUZZ_BAIL(); }
if (count == 0) { FUZZ_BAIL(); }
unsigned int item = (unsigned int) (*FUZZ_PARAM(unsigned int) % count);
unsigned char *data = nullptr; size_t len = 0;
int rc = nestegg_track_codec_data(context, track, item, &data, &len);
if (rc != 0) { FUZZ_BAIL(); }
// Data is owned by the context; we do not modify or free it
// Keep context alive

// Query video params for a video track. We just pass a local container.
unsigned int tracks = 0;
if (nestegg_track_count(context, &tracks) != 0) { FUZZ_BAIL(); }
if (tracks == 0) { FUZZ_BAIL(); }
unsigned int track = (unsigned int) (*FUZZ_PARAM(unsigned int) % tracks);
nestegg_video_params params; memset(&params, 0, sizeof(params));
int rc = nestegg_track_video_params(context, track, &params);
if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive

// Query audio params for a track. We just pass a local container.
unsigned int tracks = 0;
if (nestegg_track_count(context, &tracks) != 0) { FUZZ_BAIL(); }
if (tracks == 0) { FUZZ_BAIL(); }
unsigned int track = (unsigned int) (*FUZZ_PARAM(unsigned int) % tracks);
nestegg_audio_params params; memset(&params, 0, sizeof(params));
int rc = nestegg_track_audio_params(context, track, &params);
if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive

// Query encoding type for a valid track
unsigned int tracks = 0;
if (nestegg_track_count(context, &tracks) != 0) { FUZZ_BAIL(); }
if (tracks == 0) { FUZZ_BAIL(); }
unsigned int track = (unsigned int) (*FUZZ_PARAM(unsigned int) % tracks);
int enc = nestegg_track_encoding(context, track);
if (enc < 0) { FUZZ_BAIL(); }
// Keep context alive

// Query encryption key id for a track, if present
unsigned int tracks = 0;
if (nestegg_track_count(context, &tracks) != 0) { FUZZ_BAIL(); }
if (tracks == 0) { FUZZ_BAIL(); }
unsigned int track = (unsigned int) (*FUZZ_PARAM(unsigned int) % tracks);
unsigned char const *key = nullptr; size_t key_len = 0;
int rc = nestegg_track_content_enc_key_id(context, track, &key, &key_len);
