unsigned int track = (unsigned int) (*FUZZ_PARAM(unsigned int) % tracks);
uint64_t dur = 0;
int rc = nestegg_track_default_duration(context, track, &dur);
if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive

// Reset parser state after a read error. We invoke regardless of prior state.
