if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive

// Retrieve the last packet for a valid track without advancing state
unsigned int tracks = 0;
if (nestegg_track_count(context, &tracks) != 0) { FUZZ_BAIL(); }
if (tracks == 0) { FUZZ_BAIL(); }
unsigned int track = (unsigned int) (*FUZZ_PARAM(unsigned int) % tracks);
nestegg_packet *pkt = nullptr;
int rc = nestegg_read_last_packet(context, track, &pkt);
if (rc != 0) { FUZZ_BAIL(); }
FUZZ_ASSERT(pkt != nullptr, "nestegg_read_last_packet must set packet on success");
FUZZ_SET_ATTR_PTR((void *) pkt, "parent_ctx", (void *) context);
// Provide both context and packet as outputs
nestegg_packet *packet = pkt;

// Read at most one packet and correctly handle tri-state return.
// We do not persist the packet in the pool here to keep outputs consistent.
nestegg_packet *pkt = nullptr;
int r = nestegg_read_packet(context, &pkt);
if (r == -1) { FUZZ_BAIL(); }
if (r == 1) {
  FUZZ_ASSERT(pkt != nullptr, "nestegg_read_packet must set packet on success");
  // Mark that reading has begun; required by APIs like read_total_frames_count
  FUZZ_SET_ATTR_INT(context, "read_started", 1);
  // Packet must be freed if not returned as an output
  nestegg_free_packet(pkt);
} else if (r == 0) {
  // End of stream: nothing to do; keep context alive
} else {
  FUZZ_BAIL();
}
// Provide context back to the pool for continued use

// Must be called before any call to nestegg_read_packet per API contract
int started = FUZZ_GET_ATTR_INT(context, "read_started");
if (started != 0) { FUZZ_BAIL(); }
uint64_t frames = 0;
int rc = nestegg_read_total_frames_count(context, &frames);
if (rc != 0) { FUZZ_BAIL(); }
// Keep context alive for further calls

