if (rc != 0) { FUZZ_BAIL(); }
// Keep packet alive

// Query packet duration
uint64_t dur = 0;
int rc = nestegg_packet_duration(packet, &dur);
if (rc != 0) { FUZZ_BAIL(); }
// Keep packet alive

// Query number of chunks in the packet
unsigned int count = 0;
int rc = nestegg_packet_count(packet, &count);
if (rc != 0) { FUZZ_BAIL(); }
// Keep packet alive

// Retrieve a specific data chunk; first discover valid range via packet_count
unsigned int count = 0;
