if (count == 0) { FUZZ_BAIL(); }
unsigned int item = (unsigned int)(*FUZZ_PARAM(unsigned int) % count);
unsigned char *data = nullptr;
size_t len = 0;
int rc = nestegg_packet_data(packet, item, &data, &len);
