unsigned int id = (unsigned int)(*FUZZ_PARAM(unsigned int) % 4u); // keep ids small
unsigned char *data = nullptr;
size_t len = 0;
int rc = nestegg_packet_additional_data(packet, id, &data, &len);
if (rc != 0) { FUZZ_BAIL(); }
// Ownership remains with packet
// Keep packet alive

// Query discard_padding value in nanoseconds
int64_t dp = 0;
int rc = nestegg_packet_discard_padding(packet, &dp);
if (rc != 0) { FUZZ_BAIL(); }
// Keep packet alive

// Determine encryption/signaling status; accept any defined return or -1 on error -> bail
int enc = nestegg_packet_encryption(packet);
if (enc < -1) { FUZZ_BAIL(); }
// Keep packet alive

